        "id": "C",
        "text": "'Detailed discussion held regarding clozapine indications, benefits, and material risks including agranulocytosis (mandatory FBC monitoring), myocarditis, severe constipation, seizures, and metabolic syndrome. Patient asked questions regarding blood tests, demonstrated understanding of warning symptoms, expressed willing agreement, and retained capacity.'"
