    "questionText": "A 45-year-old man with chronic schizophrenia presents to an emergency department with severe acute chest pain radiating to his left jaw. The triage nurse notices he is responding to internal stimuli and mutters: 'He's just hallucinating again,' placing him in a psychiatric holding cubicle without obtaining an ECG, troponin, or vital signs. The patient dies two hours later of an acute myocardial infarction. What systemic human rights issue and clinical phenomenon is illustrated?",
