    "questionText": "In a randomized controlled trial evaluating a psychoeducational intervention for caregivers of patients with bipolar disorder, researchers divide participants into subgroups based on caregiver gender and baseline depression severity before performing random assignment within each subgroup. What randomization technique is being utilized?",
