    "questionText": "A hospital introduces a zero-tolerance seclusion reduction policy. The nurse quality team collects monthly ward seclusion rates for 24 consecutive months before the policy change and 24 consecutive months after the policy launch. What quantitative research design is this, and what is its major analytical strength?",
