    "questionText": "An observational study observes that psychiatric patients who drink coffee have higher rates of panic attacks than non-coffee drinkers. However, researchers discover that coffee drinkers smoke tobacco at three times the rate of non-coffee drinkers, and nicotine induces intense autonomic sympathetic arousal. In epidemiological terms, what role does tobacco smoking play in this relationship?",
