    "correctAnswer": "C",
    "explanation": "A confounding variable is an extraneous factor that is (1) associated with the exposure (coffee drinking), (2) independently causally related to the outcome (panic attacks), and (3) not an intermediate step in the causal pathway between exposure and outcome. Failure to control for tobacco smoking would lead to spurious conclusions regarding coffee and panic.",
