    "explanation": "The five domains of the Cochrane RoB 2 tool are: (1) Bias arising from the randomization process; (2) Bias due to deviations from intended interventions; (3) Bias due to missing outcome data; (4) Bias in measurement of the outcome; and (5) Bias in selection of the reported result. Financial credit ratings of administrators are completely irrelevant to trial methodology.",
