    "questionText": "A psychiatric screening tool for depression (PHQ-9) has a sensitivity of 88% and specificity of 88%. If this tool is deployed in a primary care clinic where the true prevalence of depression is 10%, how does this low prevalence affect the Positive Predictive Value (PPV) compared to testing a high-prevalence psychiatric outpatient population?",
