    "correctAnswer": "D",
    "explanation": "While Sensitivity and Specificity are intrinsic diagnostic test characteristics, Predictive Values (PPV and NPV) depend heavily on baseline population prevalence (Bayes' Theorem). When a condition is rare in a screened population (e.g., 10%), even with high 88% specificity, false positives outnumber true positives, lowering PPV (in this case to approximately 45%).",
