    "correctAnswer": "B",
    "explanation": "Selection bias occurs when participants in one study group systematically differ in prognostic characteristics from those in another group due to flaws in sampling, recruitment, or non-random group allocation. This prevents fair comparisons and introduces major systematic distortion.",
